import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import test from 'node:test';

const directory = dirname(fileURLToPath(import.meta.url));
const checker = join(directory, 'check-links.mjs');

test('accepts files and documented directories, rejects undocumented directories, and ignores fenced links', () => {
  const root = mkdtempSync(join(directory, '.check-links-'));
  try {
    mkdirSync(join(root, 'readme-dir'));
    mkdirSync(join(root, 'index-dir'));
    mkdirSync(join(root, 'empty-dir'));
    writeFileSync(join(root, 'file.md'), '# file');
    writeFileSync(join(root, 'readme-dir', 'README.md'), '# readme');
    writeFileSync(join(root, 'index-dir', 'index.md'), '# index');
    const document = join(root, 'links.md');
    writeFileSync(document, [
      '[file](file.md) [readme](readme-dir) [index](index-dir)',
      '```md',
      '[ignored](empty-dir) [missing](does-not-exist.md)',
      '```',
      '',
    ].join('\n'));

    const valid = spawnSync(process.execPath, [checker, root], { encoding: 'utf8' });
    assert.equal(valid.status, 0, valid.stderr);
    assert.match(valid.stdout, /Checked 3 local Markdown file links\./);

    writeFileSync(document, '[empty](empty-dir)\n', { flag: 'a' });
    const invalid = spawnSync(process.execPath, [checker, root], { encoding: 'utf8' });
    assert.equal(invalid.status, 1);
    assert.match(invalid.stderr, /links\.md:6: empty-dir/);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

